package com.brightloop.tax;
import com.brightloop.catalog.Product;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;import java.time.Instant;
@Entity @Table(name="taxes") public class Tax {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(nullable=false,length=120) String name;@Column(name="tax_type",nullable=false,length=20) String taxType;@Column(nullable=false,precision=12,scale=4) BigDecimal rate;@Column(length=500) String description;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id") Product product;@Column(name="effective_start") LocalDate effectiveStart;@Column(name="effective_end") LocalDate effectiveEnd;@Column(nullable=false) boolean active=true;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();protected Tax(){} public Tax(String n,String t,BigDecimal r,String d,Product p,LocalDate s,LocalDate e,boolean a){name=n;taxType=t;rate=r;description=d;product=p;effectiveStart=s;effectiveEnd=e;active=a;}public Long getId(){return id;}public String getName(){return name;}public String getTaxType(){return taxType;}public BigDecimal getRate(){return rate;}public String getDescription(){return description;}public Product getProduct(){return product;}public LocalDate getEffectiveStart(){return effectiveStart;}public LocalDate getEffectiveEnd(){return effectiveEnd;}public boolean isActive(){return active;}public void update(String n,String t,BigDecimal r,String d,Product p,LocalDate s,LocalDate e,boolean a){name=n;taxType=t;rate=r;description=d;product=p;effectiveStart=s;effectiveEnd=e;active=a;}}
